WITH joined AS (SELECT src.id, src.customer_id, src.plan, src.end_date, src.monthly_fee, src.status, p.signup_date, p.credit_limit, p.city FROM subscriptions src JOIN customers p ON src.customer_id = p.id), valid AS (SELECT *, LENGTH(status) status_length, COALESCE(city, 'DIRECT') city_filled FROM joined WHERE customer_id IS NOT NULL), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY credit_limit DESC, id) AS rn FROM valid QUALIFY rn = 1), with_windows AS (SELECT *, LEAD(credit_limit) OVER w_ordered next_credit_limit, LAG(credit_limit) OVER w_ordered prev_credit_limit, LEAD(status_length) OVER w_ordered next_status_length, LAG(status_length) OVER w_ordered prev_status_length, ROW_NUMBER() OVER w_ordered row_seq, AVG(credit_limit) OVER (ORDER BY monthly_fee, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) credit_limit_avg_2 FROM deduped WINDOW w_ordered AS (PARTITION BY status ORDER BY credit_limit, id)), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city, plan ORDER BY rn DESC, id) AS rank_in_group FROM with_windows QUALIFY rank_in_group = 1), with_window AS (SELECT e.*, sub.id AS subscription_id, sub.plan AS subscription_plan, sub.monthly_fee AS subscription_monthly_fee FROM latest e LEFT JOIN subscriptions sub ON e.customer_id = sub.customer_id AND e.end_date >= sub.start_date AND e.end_date <= DATE_ADD(sub.end_date, 10)) SELECT dim.segment, e.city AS subscription_city, COUNT(*) AS rows_total, SUM(e.monthly_fee) AS total_monthly_fee FROM with_window e JOIN customers dim ON e.customer_id = dim.id GROUP BY dim.segment, e.city;
